import axios, { type AxiosInstance } from "axios";
import { useAuthStore } from "@/shared/stores/auth.store";
import { useServerStore } from "@/shared/stores/server.store";

let apiInstance: AxiosInstance | null = null;

export function useApiInstance() {
  if (!apiInstance) {
    apiInstance = axios.create({
      timeout: 30000,
      headers: {
        "Content-Type": "application/json",
        "Request-Type": "json",
      },
    });

    apiInstance.interceptors.request.use(
      async (config) => {
        const serverStore = useServerStore();
        const authStore = useAuthStore();

        if (serverStore.baseUrl) {
          config.baseURL = serverStore.baseUrl;
        }

        const token = await authStore.getToken();
        if (token) {
          config.headers.set("Access-Token", token);
        }

        return config;
      },
      (error) => Promise.reject(error),
    );

    apiInstance.interceptors.response.use(
      (response) => {
        if (response.data?.error) {
          console.error(
            "[API] Error:",
            response.data.error.data?.message || response.data.error,
          );
        }
        return response;
      },
      (error) => {
        console.error("[API] Network Error:", error.message);
        return Promise.reject(error);
      },
    );
  }

  return apiInstance;
}
