import { f7 } from "framework7-vue";
import { useAuthStore } from "@/shared/stores/auth.store";

export function useAuthGuard() {
  const authStore = useAuthStore();
  const publicRoutes = ["/login", "/onboarding"];

  const checkAuth = (path: string) => {
    const isPublic = publicRoutes.some((p) => path?.startsWith(p));

    if (!authStore.isAuthenticated && !isPublic) {
      f7.views.main?.router.navigate("/login", {
        reloadAll: true,
        animate: false,
      });
      return false;
    }
    return true;
  };

  f7.on("routeChange", (newRoute) => {
    checkAuth(newRoute.path);
  });

  const currentRoute = f7.views.main?.router.currentRoute;
  if (currentRoute) {
    checkAuth(currentRoute.path);
  } else {
    if (!authStore.isAuthenticated) {
      const currentPath = window.location.pathname;
      if (
        !publicRoutes.some((p) => currentPath?.startsWith(p)) &&
        !window.location.hash.includes("login")
      ) {
        f7.views.main?.router.navigate("/login", {
          reloadAll: true,
          animate: false,
        });
      }
    }
  }
}
