/**
 * Auth Store
 *
 * Manages authentication state with secure token storage via Capacitor Preferences.
 * Compatible with the old efficyapp Auth service pattern.
 */

import { Preferences } from "@capacitor/preferences";

export interface UserSession {
  token: string;
  expires: number;
}

export interface AuthUser {
  ruid: string;
  name: string;
  permissions: string[];
}

const TOKEN_KEY = "accessToken";
const SESSION_KEY = "user-session";
const USER_KEY = "user-state";

export const useAuthStore = defineStore("auth", () => {
  const session = ref<UserSession | null>(null);
  const user = ref<AuthUser | null>(null);
  const isLoading = ref(true);

  const isAuthenticated = computed(
    () => !!session.value?.token && session.value.expires > Date.now(),
  );

  const token = computed(() => session.value?.token ?? null);

  /**
   * Initialize auth state from Preferences.
   */
  async function init() {
    isLoading.value = true;
    try {
      const { value: sessionJson } = await Preferences.get({
        key: SESSION_KEY,
      });
      if (sessionJson) {
        session.value = JSON.parse(sessionJson);
      }

      const { value: userJson } = await Preferences.get({ key: USER_KEY });
      if (userJson) {
        user.value = JSON.parse(userJson);
      }
    } catch (e) {
      console.error("[AuthStore] Failed to load state", e);
    } finally {
      isLoading.value = false;
    }
  }

  /**
   * Set session after successful login.
   */
  async function setSession(newSession: UserSession) {
    session.value = newSession;

    await Preferences.set({
      key: TOKEN_KEY,
      value: newSession.token,
    });

    await Preferences.set({
      key: SESSION_KEY,
      value: JSON.stringify(newSession),
    });
  }

  /**
   * Set current user info.
   */
  async function setUser(newUser: AuthUser) {
    user.value = newUser;

    await Preferences.set({
      key: USER_KEY,
      value: JSON.stringify(newUser),
    });
  }

  /**
   * Get token for API requests (async for compatibility).
   */
  async function getToken(): Promise<string | null> {
    if (session.value?.token) {
      return session.value.token;
    }

    // Fallback: try to load from Preferences
    const { value } = await Preferences.get({ key: TOKEN_KEY });
    return value ?? null;
  }

  async function getSession(): Promise<UserSession | null> {
    const { value: sessionJson } = await Preferences.get({
      key: SESSION_KEY,
    });
    if (sessionJson) {
      return JSON.parse(sessionJson);
    }
    return null;
  }

  /**
   * Clear all auth state (logout).
   */
  async function logout() {
    session.value = null;
    user.value = null;

    await Preferences.remove({ key: TOKEN_KEY });
    await Preferences.remove({ key: SESSION_KEY });
    await Preferences.remove({ key: USER_KEY });
  }

  /**
   * Check if user has a specific permission.
   */
  function hasPermission(permission: string): boolean {
    return user.value?.permissions.includes(permission) ?? false;
  }

  return {
    // State
    session,
    user,
    isLoading,
    isAuthenticated,
    token,

    // Actions
    init,
    setSession,
    setUser,
    getToken,
    getSession,
    logout,
    hasPermission,
  };
});
