/**
 * Sync Transport (Axios-based)
 *
 * HTTP adapter for sync API calls using axios.
 * Uses stores for dynamic base URL and auth token.
 */

import type { AxiosInstance } from "axios";
import { useApiInstance } from "@/shared/composables/utils/useApiInstance";
import type {
  StatusStepResponse,
  RecordPing,
  PersistStepResponse,
} from "./types";

export class SyncTransportError extends Error {
  constructor(
    message: string,
    public statusCode?: number,
    public responseData?: unknown,
  ) {
    super(message);
    this.name = "SyncTransportError";
  }
}

/**
 * Backend response wrapper (matches old efficyapp format)
 */
interface BackendResponse<T> {
  result: T;
  error?: {
    data: {
      message: string;
    };
  };
}

/**
 * HTTP transport for sync operations.
 */
export class SyncTransport {
  private api: AxiosInstance;

  constructor() {
    this.api = useApiInstance();
  }

  /**
   * Step 1: Status - Compare local records with server
   */
  async status(
    table: string,
    records: RecordPing[],
  ): Promise<StatusStepResponse> {
    const response = await this.api.post<BackendResponse<StatusStepResponse>>(
      `/api/sync/${table}/step1/status`,
      { objects: records },
    );
    console.log(
      `[SyncTransport] Status response for ${table}:`,
      response.status,
    );

    if (response.data.error) {
      throw new SyncTransportError(response.data.error.data.message);
    }

    return response.data.result;
  }

  /**
   * Step 2: Fetch - Download records by ruid
   */
  async fetch<T = Record<string, unknown>>(
    table: string,
    ruids: string[],
  ): Promise<T[]> {
    if (ruids.length === 0) return [];

    const response = await this.api.post<BackendResponse<T[]>>(
      `/api/sync/${table}/step2/fetch`,
      { ruids, context: { efficy: true } },
    );

    if (response.data.error) {
      throw new SyncTransportError(response.data.error.data.message);
    }

    return response.data.result;
  }

  /**
   * Step 3: Persist - Upload local changes
   */
  async persist<T = Record<string, unknown>>(
    table: string,
    records: T[],
  ): Promise<PersistStepResponse> {
    if (records.length === 0) {
      return { done: [], failed: [] };
    }

    const response = await this.api.post<BackendResponse<PersistStepResponse>>(
      `/api/sync/${table}/step3/persist`,
      { objects: records },
    );

    if (response.data.error) {
      throw new SyncTransportError(response.data.error.data.message);
    }

    return response.data.result;
  }

  /**
   * Upload a file (multipart/form-data)
   */
  async uploadFile(file: Blob, fileName: string): Promise<{ url: string }> {
    const formData = new FormData();
    formData.append("file", file, fileName);

    const response = await this.api.post<{ url: string }>(
      "/api/upload",
      formData,
      {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      },
    );

    return response.data;
  }

  /**
   * Download a file (returns Blob)
   */
  async downloadFile(url: string): Promise<Blob> {
    const response = await this.api.get(url, {
      responseType: "blob",
    });

    return response.data;
  }
}

/** Singleton transport instance */
let transportInstance: SyncTransport | null = null;

/** Initialize the sync transport */
export function initSyncTransport(): SyncTransport {
  transportInstance = new SyncTransport();
  return transportInstance;
}

/** Get the sync transport instance */
export function getSyncTransport(): SyncTransport {
  if (!transportInstance) {
    // Auto-initialize if not done yet
    transportInstance = new SyncTransport();
  }
  return transportInstance;
}
