/**
 * Sync Configuration Registry
 *
 * This file is ONLY for aggregating sync configurations from modules.
 * It uses auto-discovery (import.meta.glob) to find 'sync.ts' in src/modules.
 */

import type { SyncTableConfig } from "./types";

// Auto-load all *.sync.ts files from database folders in modules
const modules = import.meta.glob<{ syncConfig: SyncTableConfig[] }>(
  "../../modules/*/database/*.sync.ts",
  { eager: true },
);

/**
 * Aggregated sync tables from all modules.
 */
export const syncTables: SyncTableConfig[] = [
  ...Object.values(modules).flatMap((mod) => mod.syncConfig || []),
  // Deduplicate by table name if necessary, but for now just concat
].filter(
  (t, index, self) => index === self.findIndex((s) => s.table === t.table),
);

console.log("[SyncConfig] Loaded modules:", Object.keys(modules));
console.log("[SyncConfig] Aggregated tables:", syncTables);
