/**
 * Countries Module Sync Configuration
 *
 * Syncs with the res.country model from the backend.
 * This is a simple lookup table that syncs on every sync run (pull-only).
 */

import type { SyncTableConfig } from "@/shared/sync/types";

export const syncConfig: SyncTableConfig[] = [
  {
    table: "res.country",
    localTable: "res_country",
    direction: "pull", // Read-only from server
    priority: 1, // High priority - needed by other tables
    delayMinutes: 0, // Sync every time
    conflictStrategy: "server_wins",
    fields: ["name", "code", "phone_code", "currency_id"],
  },
];
